1	import { vi } from "vitest";
2	import { runInNewContext } from "node:vm";
3	import { H3, HTTPError, type H3Event } from "../src/index.ts";
4	import { describeMatrix } from "./_setup.ts";
5	
6	describeMatrix("errors", (t, { it, expect, describe }) => {
7	  const consoleMock = ((globalThis.console.error as any) = vi.fn());
8	
9	  describe("error response bodies", () => {
10	    for (const withOnError of [false, true]) {
11	      const hook = withOnError ? "with onError" : "without onError";
12	
13	      it(`omits the body for a missing HEAD route ${hook}`, async () => {
14	        if (!withOnError) t.app.config.onError = undefined;
15	        const res = await t.fetch("/missing", { method: "HEAD" });
16	        expect(res.status).toBe(404);
17	        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
18	        expect(res.headers.get("content-length")).toBeNull();
19	        expect(await res.text()).toBe("");
20	        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
21	        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
22	      });
23	
24	      for (const asyncHandler of [false, true]) {
25	        for (const method of ["GET", "HEAD"]) {
26	          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
27	            if (!withOnError) t.app.config.onError = undefined;
28	            const handler = (event: H3Event) => {
29	              event.res.headers.set("x-success", "success");
30	              event.res.errHeaders.set("x-error", "prepared");
31	              event.res.errHeaders.append("set-cookie", "prepared=1");
32	              throw new HTTPError({
33	                status: 422,
34	                statusText: "Unprocessable",
35	                data: { test: 123 },
36	                headers: { "x-error-own": "own", "set-cookie": "error=1" },
37	              });
38	            };
39	            t.app.use(asyncHandler ? async (event) => handler(event) : handler);
40	
41	            const res = await t.fetch("/", { method });
42	            expect(res.status).toBe(422);
43	            expect(res.statusText).toBe("Unprocessable");
44	            expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
45	            expect(res.headers.get("x-error")).toBe("prepared");
46	            expect(res.headers.get("x-error-own")).toBe("own");
47	            expect(res.headers.get("x-success")).toBeNull();
48	            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
49	            if (method === "HEAD") {
50	              expect(res.headers.get("content-length")).toBeNull();
51	              expect(await res.text()).toBe("");
52	            } else {
53	              expect(await res.json()).toMatchObject({
54	                status: 422,
55	                statusText: "Unprocessable",
56	                data: { test: 123 },
57	              });
58	            }
59	            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
60	            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
61	          });
62	        }
63	      }
64	    }
65	  });
66	
67	  it("throw HTTPError", async () => {
68	    t.app.use(() => {
69	      throw new HTTPError({
70	        statusText: "Unprocessable",
71	        status: 422,
72	        data: { test: 123 },
73	        body: { topLevel: "works" },
74	      });
75	    });
76	    const result = await t.fetch("/");
77	    expect(result.status).toBe(422);
78	    expect(result.statusText).toBe("Unprocessable");
79	    expect(await result.json()).toMatchObject({
80	      status: 422,
81	      statusText: "Unprocessable",
82	      message: "Unprocessable",
83	      data: { test: 123 },
84	      topLevel: "works",
85	    });
86	  });
87	
88	  it("return HTTPError", async () => {
89	    t.app.use(() => {
90	      return new HTTPError({
91	        statusText: "Unprocessable",
92	        status: 422,
93	        data: { test: 123 },
94	      });
95	    });
96	    const result = await t.fetch("/");
97	    expect(result.status).toBe(422);
98	    expect(result.statusText).toBe("Unprocessable");
99	    expect(await result.json()).toMatchObject({
100	      status: 422,
101	      statusText: "Unprocessable",
102	      message: "Unprocessable",
103	      data: { test: 123 },
104	    });
105	  });
106	
107	  it("unandled errors", async () => {
108	    t.app.use("/api/test", () => {
109	      // @ts-expect-error
110	      foo.bar = 123;
111	    });
112	    const result = await t.fetch("/api/test");
113	
114	    expect(t.errors[0].message).toMatch("foo is not defined");
115	    expect(t.errors[0].unhandled).toBe(true);
116	    t.errors = [];
117	
118	    expect(result.status).toBe(500);
119	    expect(JSON.parse(await result.text())).toMatchObject({
120	      status: 500,
121	    });
122	  });
123	
124	  it("can send runtime error", async () => {
125	    consoleMock.mockReset();
126	
127	    t.app.get("/api/test", () => {
128	      throw new HTTPError({
129	        status: 400,
130	        statusText: "Bad Request",
131	        data: {
132	          message: "Invalid Input",
133	        },
134	      });
135	    });
136	
137	    const result = await t.fetch("/api/test");
138	
139	    expect(result.status).toBe(400);
140	    expect(result.headers.get("content-type")).toMatch("application/json");
141	
142	    expect(console.error).not.toBeCalled();
143	
144	    expect(JSON.parse(await result.text())).toMatchObject({
145	      status: 400,
146	      statusText: "Bad Request",
147	      data: {
148	        message: "Invalid Input",
149	      },
150	    });
151	  });
152	
153	  it("can access original error", async () => {
154	    class CustomError extends Error {
155	      customError = true;
156	    }
157	
158	    t.app.get("/", () => {
159	      throw new HTTPError(new CustomError());
160	    });
161	
162	    const res = await t.fetch("/");
163	    expect(res.status).toBe(500);
164	
165	    expect(t.errors[0].cause).toBeInstanceOf(CustomError);
166	  });
167	
168	  it("can inherit from cause", async () => {
169	    class CustomError extends Error {
170	      override cause = new HTTPError({
171	        status: 400,
172	        statusText: "Bad Request",
173	        unhandled: true,
174	      });
175	    }
176	
177	    t.app.get("/", () => {
178	      throw new HTTPError(new CustomError());
179	    });
180	
181	    const res = await t.fetch("/");
182	    expect(res.status).toBe(400);
183	    expect(t.errors[0].unhandled).toBe(true);
184	
185	    t.errors = [];
186	  });
187	
188	  it("can inherit deprecated statusCode/statusMessage from cause", async () => {
189	    const cause = { statusCode: 404, statusMessage: "Not Found" };
190	
191	    t.app.get("/", () => {
192	      throw new HTTPError({ cause });
193	    });
194	
195	    const res = await t.fetch("/");
196	    expect(res.status).toBe(404);
197	    expect(res.statusText).toBe("Not Found");
198	
199	    t.errors = [];
200	  });
201	
202	  it("error headers", async () => {
203	    t.app.config.onError = async (error, event) => {
204	      const headers = new Headers(event.res.headers);
205	      headers.set("set-cookie", "error=1");
206	      return new Response(error.toString(), { status: 501, headers });
207	    };
208	
209	    t.app.get("/", async (event) => {
210	      event.res.headers.set("set-cookie", "auth=1");
211	      event.res.headers.set("x-test", "1");
212	      throw new HTTPError("test");
213	    });
214	
215	    const res = await t.fetch("/");
216	    expect(res.status).toBe(501);
217	    expect(res.headers.get("x-test")).toBe("1");
218	    expect(res.headers.getSetCookie()).toEqual(["error=1"]);
219	
220	    t.errors = [];
221	  });
222	
223	  it("throw number coerces to status", async () => {
224	    t.app.use(() => {
225	      throw 404;
226	    });
227	    const res = await t.fetch("/");
228	    expect(res.status).toBe(404);
229	  });
230	
231	  it("throw async number coerces to status", async () => {
232	    t.app.use(async () => {
233	      throw 500;
234	    });
235	    const res = await t.fetch("/");
236	    expect(res.status).toBe(500);
237	  });
238	
239	  it("return number is unchanged", async () => {
240	    t.app.use(() => 404);
241	    const res = await t.fetch("/");
242	    expect(res.status).toBe(200);
243	    expect(await res.json()).toBe(404);
244	  });
245	
246	  describe("non-Error throws", () => {
247	    it("throw object does not leak into the response body", async () => {
248	      t.app.use(() => {
249	        throw { secret: "db-password", message: "internal detail", status: 403 };
250	      });
251	      const res = await t.fetch("/");
252	      // A non-Error object is always an unhandled 500; nothing on it shapes the response
253	      expect(res.status).toBe(500);
254	      const body = await res.text();
255	      expect(body).not.toContain("db-password");
256	      expect(body).not.toContain("internal detail");
257	      expect(JSON.parse(body)).toMatchObject({ status: 500, unhandled: true });
258	
259	      expect(t.errors[0].unhandled).toBe(true);
260	      expect(t.errors[0].cause).toMatchObject({ secret: "db-password" });
261	      t.errors = [];
262	    });
263	
264	    // A non-Error object is never trusted to shape the response, not even via a `status` shorthand
265	    // (unlike `throw 404`). `status` / `statusCode` / `statusText` / `headers` are all dropped.
266	    it("status on a thrown object is never honored", async () => {
267	      const shapes = [
268	        { status: 403 },
269	        { statusCode: 429 },
270	        { status: 400, statusText: "Leaky Status Text" },
271	      ];
272	      for (const [i, shape] of shapes.entries()) {
273	        t.app.get(`/shape-${i}`, () => {
274	          throw shape;
275	        });
