describe("problem details (RFC 9457)", () => {
  const problemType = "application/problem+json;charset=UTF-8";

  it("RF-01: content-type for thrown, number, missing route and middleware errors", async () => {
    t.app.get("/thrown", () => {
      throw new HTTPError({ status: 400 });
    });
    t.app.get("/number", () => {
      throw 404;
    });
    t.app.get("/mw", () => "ok", {
      middleware: [
        () => {
          throw new HTTPError({ status: 401 });
        },
      ],
    });
    for (const [path, status] of [
      ["/thrown", 400],
      ["/number", 404],
      ["/missing", 404],
      ["/mw", 401],
    ] as const) {
      const res = await t.fetch(path);
      expect(res.status).toBe(status);
      expect(res.headers.get("content-type")).toBe(problemType);
      expect(await res.json()).toMatchObject({ type: "about:blank", status });
    }
  });

  it("RF-02/RF-03/RF-06: members, type, instance and extensions in the body", async () => {
    t.app.get("/", () => {
      throw new HTTPError({
        status: 403,
        statusText: "Forbidden",
        message: "Saldo insuficiente",
        type: "https://example.com/probs/sem-saldo",
        instance: "/contas/12/saques/7",
        data: { campo: "email" },
        body: { traceId: "abc", status: 200 },
      });
    });
    const res = await t.fetch("/");
    expect(await res.json()).toMatchObject({
      type: "https://example.com/probs/sem-saldo",
      title: "Forbidden",
      status: 403,
      detail: "Saldo insuficiente",
      instance: "/contas/12/saques/7",
      data: { campo: "email" },
      traceId: "abc",
    });
  });

  it("RF-04: no instance key when absent", async () => {
    t.app.get("/", () => {
      throw new HTTPError("falhou");
    });
    const body = await (await t.fetch("/")).json();
    expect(body.type).toBe("about:blank");
    expect("instance" in body).toBe(false);
  });

  it("RF-05: unhandled error does not leak", async () => {
    t.app.get("/", () => {
      throw Object.assign(new Error("segredo interno"), { type: "t", instance: "i" });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(res.headers.get("content-type")).toBe(problemType);
    const text = await res.text();
    expect(text).not.toContain("segredo interno");
    expect(text).not.toContain("stack");
    const body = JSON.parse(text);
    expect(body.type).toBe("about:blank");
    expect("instance" in body).toBe(false);
    expect("detail" in body).toBe(false);
    t.errors = [];
  });

  it("RF-05: unhandled error from a node handler does not leak type", async () => {
    t.app.get(
      "/",
      fromNodeHandler(() => {
        throw Object.assign(new Error("segredo interno"), { type: "t", instance: "i" });
      }),
    );
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    const text = await res.text();
    expect(text).not.toContain("segredo interno");
    expect(JSON.parse(text).type).toBe("about:blank");
    t.errors = [];
  });

  it("RF-07: debug keeps stack, indentation and headers", async () => {
    t.app.config.debug = true;
    t.app.get("/", () => {
      throw new HTTPError({ status: 400, headers: { "x-id": "1" } });
    });
    const res = await t.fetch("/");
    expect(res.headers.get("x-id")).toBe("1");
    expect(res.headers.get("content-type")).toBe(problemType);
    const text = await res.text();
    expect(text).toContain('\n  "status"');
    expect(Array.isArray(JSON.parse(text).stack)).toBe(true);
  });

  it("RF-08: success JSON keeps application/json", async () => {
    t.app.get("/", () => ({ ok: true }));
    const res = await t.fetch("/");
    expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
  });
});

