import { vi } from "vitest";
import { runInNewContext } from "node:vm";
import { H3, HTTPError, fromNodeHandler, type H3Event } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("errors", (t, { it, expect, describe }) => {
  const consoleMock = ((globalThis.console.error as any) = vi.fn());

  describe("error response bodies", () => {
    for (const withOnError of [false, true]) {
      const hook = withOnError ? "with onError" : "without onError";

      it(`omits the body for a missing HEAD route ${hook}`, async () => {
        if (!withOnError) t.app.config.onError = undefined;
        const res = await t.fetch("/missing", { method: "HEAD" });
        expect(res.status).toBe(404);
        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
        expect(res.headers.get("content-length")).toBeNull();
        expect(await res.text()).toBe("");
        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
      });

      for (const asyncHandler of [false, true]) {
        for (const method of ["GET", "HEAD"]) {
          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
            if (!withOnError) t.app.config.onError = undefined;
            const handler = (event: H3Event) => {
              event.res.headers.set("x-success", "success");
              event.res.errHeaders.set("x-error", "prepared");
              event.res.errHeaders.append("set-cookie", "prepared=1");
              throw new HTTPError({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
                headers: { "x-error-own": "own", "set-cookie": "error=1" },
              });
            };
            t.app.use(asyncHandler ? async (event) => handler(event) : handler);

            const res = await t.fetch("/", { method });
            expect(res.status).toBe(422);
            expect(res.statusText).toBe("Unprocessable");
            expect(res.headers.get("content-type")).toBe(
              "application/problem+json;charset=UTF-8",
            );
            expect(res.headers.get("x-error")).toBe("prepared");
            expect(res.headers.get("x-error-own")).toBe("own");
            expect(res.headers.get("x-success")).toBeNull();
            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
            if (method === "HEAD") {
              expect(res.headers.get("content-length")).toBeNull();
              expect(await res.text()).toBe("");
            } else {
              expect(await res.json()).toMatchObject({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
              });
            }
            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
          });
        }
      }
    }
  });

  it("throw HTTPError", async () => {
    t.app.use(() => {
      throw new HTTPError({
        statusText: "Unprocessable",
        status: 422,
        data: { test: 123 },
        body: { topLevel: "works" },
      });
    });
    const result = await t.fetch("/");
    expect(result.status).toBe(422);
    expect(result.statusText).toBe("Unprocessable");
    expect(await result.json()).toMatchObject({
      status: 422,
      statusText: "Unprocessable",
      message: "Unprocessable",
      data: { test: 123 },
      topLevel: "works",
    });
  });

  it("return HTTPError", async () => {
    t.app.use(() => {
      return new HTTPError({
        statusText: "Unprocessable",
        status: 422,
        data: { test: 123 },
      });
    });
    const result = await t.fetch("/");
    expect(result.status).toBe(422);
    expect(result.statusText).toBe("Unprocessable");
    expect(await result.json()).toMatchObject({
      status: 422,
      statusText: "Unprocessable",
      message: "Unprocessable",
      data: { test: 123 },
    });
  });

  it("unandled errors", async () => {
    t.app.use("/api/test", () => {
      // @ts-expect-error
      foo.bar = 123;
    });
    const result = await t.fetch("/api/test");

    expect(t.errors[0].message).toMatch("foo is not defined");
    expect(t.errors[0].unhandled).toBe(true);
    t.errors = [];

    expect(result.status).toBe(500);
    expect(JSON.parse(await result.text())).toMatchObject({
      status: 500,
    });
  });

  it("can send runtime error", async () => {
    consoleMock.mockReset();

    t.app.get("/api/test", () => {
      throw new HTTPError({
        status: 400,
        statusText: "Bad Request",
        data: {
          message: "Invalid Input",
        },
      });
    });

    const result = await t.fetch("/api/test");

    expect(result.status).toBe(400);
    expect(result.headers.get("content-type")).toMatch("application/problem+json");

    expect(console.error).not.toBeCalled();

    expect(JSON.parse(await result.text())).toMatchObject({
      status: 400,
      statusText: "Bad Request",
      data: {
        message: "Invalid Input",
      },
    });
  });

  it("can access original error", async () => {
    class CustomError extends Error {
      customError = true;
    }

    t.app.get("/", () => {
      throw new HTTPError(new CustomError());
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(500);

    expect(t.errors[0].cause).toBeInstanceOf(CustomError);
  });

  it("can inherit from cause", async () => {
    class CustomError extends Error {
      override cause = new HTTPError({
        status: 400,
        statusText: "Bad Request",
        unhandled: true,
      });
    }

    t.app.get("/", () => {
      throw new HTTPError(new CustomError());
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(400);
    expect(t.errors[0].unhandled).toBe(true);

    t.errors = [];
  });

  it("can inherit deprecated statusCode/statusMessage from cause", async () => {
    const cause = { statusCode: 404, statusMessage: "Not Found" };

    t.app.get("/", () => {
      throw new HTTPError({ cause });
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(404);
    expect(res.statusText).toBe("Not Found");

    t.errors = [];
  });

  it("error headers", async () => {
    t.app.config.onError = async (error, event) => {
      const headers = new Headers(event.res.headers);
      headers.set("set-cookie", "error=1");
      return new Response(error.toString(), { status: 501, headers });
    };

    t.app.get("/", async (event) => {
      event.res.headers.set("set-cookie", "auth=1");
      event.res.headers.set("x-test", "1");
      throw new HTTPError("test");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(501);
    expect(res.headers.get("x-test")).toBe("1");
    expect(res.headers.getSetCookie()).toEqual(["error=1"]);

    t.errors = [];
  });

  it("throw number coerces to status", async () => {
    t.app.use(() => {
      throw 404;
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(404);
  });

  it("throw async number coerces to status", async () => {
    t.app.use(async () => {
      throw 500;
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
  });

  it("return number is unchanged", async () => {
    t.app.use(() => 404);
    const res = await t.fetch("/");
    expect(res.status).toBe(200);
    expect(await res.json()).toBe(404);
  });

  describe("non-Error throws", () => {
    it("throw object does not leak into the response body", async () => {
      t.app.use(() => {
        throw { secret: "db-password", message: "internal detail", status: 403 };
      });
      const res = await t.fetch("/");
      // A non-Error object is always an unhandled 500; nothing on it shapes the response
      expect(res.status).toBe(500);
      const body = await res.text();
      expect(body).not.toContain("db-password");
      expect(body).not.toContain("internal detail");
      expect(JSON.parse(body)).toMatchObject({ status: 500, unhandled: true });

      expect(t.errors[0].unhandled).toBe(true);
      expect(t.errors[0].cause).toMatchObject({ secret: "db-password" });
      t.errors = [];
    });

    // A non-Error object is never trusted to shape the response, not even via a `status` shorthand
    // (unlike `throw 404`). `status` / `statusCode` / `statusText` / `headers` are all dropped.
    it("status on a thrown object is never honored", async () => {
      const shapes = [
        { status: 403 },
        { statusCode: 429 },
        { status: 400, statusText: "Leaky Status Text" },
      ];
      for (const [i, shape] of shapes.entries()) {
        t.app.get(`/shape-${i}`, () => {
          throw shape;
        });
        const res = await t.fetch(`/shape-${i}`);
        expect(res.status).toBe(500);
        expect(res.statusText).not.toBe("Leaky Status Text");
      }
      t.errors = [];
    });

    it("throw async object does not leak into the response body", async () => {
      t.app.use(async () => {
        throw { secret: "db-password" };
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("db-password");
      t.errors = [];
    });

    it("throw string", async () => {
      t.app.use(() => {
        throw "not-an-error";
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("not-an-error");
      t.errors = [];
    });

    it("throw undefined", async () => {
      t.app.use(() => {
        throw undefined;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
      t.errors = [];
    });

    it("thrown object cannot forge response headers", async () => {
      t.app.use(() => {
        throw { headers: { "x-forged": "1" } };
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(res.headers.get("x-forged")).toBe(null);
      t.errors = [];
    });

    // `toError` must use the same `instanceof Error` check as `prepareResponse`. A broader check
    // (e.g. `Error.isError`) would pass this through, only for `prepareResponse` to reject it and
    // render it as a successful body again.
    it("cross-realm error is not rendered as a body", async () => {
      const foreign = runInNewContext(`new Error("cross-realm secret")`);
      t.app.use(() => {
        throw foreign;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("cross-realm secret");
      t.errors = [];
    });

    // Fetch clients (ky, got) throw their own errors named `HTTPError`, without `status`, whose
    // message carries the upstream request URL. They must not pass as h3 `HTTPError`s.
    it("foreign error named HTTPError without status is unhandled", async () => {
      class UpstreamHTTPError extends Error {
        override name = "HTTPError";
      }
      const foreign = new UpstreamHTTPError("Request failed: GET https://internal/?token=secret");
      expect(HTTPError.isError(foreign)).toBe(false);
      t.app.use(() => {
        throw foreign;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ unhandled: true, message: "HTTPError" });
      expect(t.errors[0].unhandled).toBe(true);
      t.errors = [];
    });

    it("onError receives the wrapped error", async () => {
      const onError = vi.fn();
      const app = new H3({ onError, silent: true });
      app.use(() => {
        throw { secret: "db-password" };
      });
      const res = await app.request("/");
      expect(res.status).toBe(500);
      expect(onError).toHaveBeenCalledTimes(1);
      const error = onError.mock.calls[0][0];
      expect(HTTPError.isError(error)).toBe(true);
      expect(error.unhandled).toBe(true);
      expect(error.cause).toMatchObject({ secret: "db-password" });
    });
  });

  // Regression for #1477: a synchronous throw while preparing the response (circular
  // `JSON.stringify`) must be routed through the same 500 pipeline as any other error,
  // not escape `fetch()` as a raw exception/rejection.
  describe("response preparation throws", () => {
    it("circular return value is rendered as a 500 instead of escaping fetch()", async () => {
      t.app.use(() => {
        const circular: any = {};
        circular.self = circular;
        return circular;
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
      t.errors = [];
    });

    it("thrown HTTPError with circular data is rendered as a 500 instead of escaping fetch() (no onError)", async () => {
      // With no `onError` configured, `errorResponse()`'s `JSON.stringify` runs
      // synchronously in the same pass as the throw (the async/onError branch is not
      // taken), so this exercises the raw synchronous-escape path directly.
      t.app.config.onError = undefined;
      t.app.use(() => {
        const data: any = {};
        data.self = data;
        throw new HTTPError({ status: 400, data });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
    });
  });

  // Regression for #1503 (CodeRabbit): a synchronously-throwing `onError` hook must not
  // recurse infinitely. `Promise.resolve(onError(error, event))` evaluates the call before
  // wrapping it in a promise, so a sync throw there escaped `prepareResponse()` synchronously.
  // That was caught by `toResponse()`'s try/catch (added for #1477) and re-entered
  // `toResponse` with `nested` reset to `false` — calling the same throwing `onError` again,
  // forever (stack overflow instead of a normalized 500).
  it("a synchronously-throwing onError does not recurse infinitely", async () => {
    t.app.config.onError = () => {
      throw new Error("onError boom");
    };
    t.app.use(() => {
      throw new Error("handler boom");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
  });

  // A value returned from `onError` replaces the response, so a value *thrown* by the hook must be
  // normalized through `toError()` first. Otherwise the two are indistinguishable and a non-Error
  // throw is rendered as a successful body: the hook's internals leak to the client and the failed
  // request reports 200.
  for (const [label, thrown] of [
    ["an object", { secret: "s3cr3t" }],
    ["a string", "leaked internal string"],
  ] as const) {
    it(`an onError throwing ${label} renders an unhandled 500, not a 200 body`, async () => {
      t.app.config.onError = () => {
        throw thrown;
      };
      t.app.use(() => {
        throw new Error("handler boom");
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      const body = await res.json();
      expect(body).toMatchObject({ status: 500, unhandled: true });
      expect(JSON.stringify(body)).not.toContain("s3cr3t");
      expect(JSON.stringify(body)).not.toContain("leaked internal string");
    });
  }

  it("an onError throwing a number renders that status", async () => {
    t.app.config.onError = () => {
      throw 418;
    };
    t.app.use(() => {
      throw new Error("handler boom");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(418);
  });
});

import type {
  EventHandler,
  EventHandlerRequest,
  HTTPHandler,
  H3Event,
  RouteDefinition,
  RouteRules,
  TypedHeaders,
  WebSocketResponse,
} from "../../src/index.ts";
import { H3 } from "../../src/index.ts";
import { describe, it, expectTypeOf } from "vitest";
import {
  defineHandler,
  getQuery,
  readBody,
  readValidatedBody,
  getValidatedQuery,
  defineValidatedHandler,
  defineWebSocketHandler,
  defineLazyEventHandler,
  defineRoute,
  toEventHandler,
  withBase,
  requireBasicAuth,
} from "../../src/index.ts";
import {
  appendHeaders,
  appendResponseHeaders,
  defineEventHandler,
  sendRedirect,
} from "../../src/_deprecated.ts";
import { z } from "zod";

describe("types", () => {
  it("exports TypedHeaders", () => {
    type RequestHeaders = TypedHeaders<{ authorization: string }>;
    const getAuthorization = (headers: RequestHeaders) => headers.get("authorization");
    expectTypeOf(getAuthorization).returns.toEqualTypeOf<string | null>();
  });

  it("event.req.headers uses request header names", () => {
    type HeaderName = Parameters<H3Event["req"]["headers"]["delete"]>[0];
    expectTypeOf<Extract<HeaderName, "Authorization">>().toEqualTypeOf<"Authorization">();
    expectTypeOf<Extract<HeaderName, "X-Powered-By">>().toBeNever();
  });

  type ReqOf<H> = H extends (event: H3Event<infer R>) => any ? R : never;

  describe("eventHandler", () => {
    it("return type (inferred)", () => {
      const handler = defineHandler(() => {
        return {
          foo: "bar",
        };
      });
      const response = handler({} as H3Event);
      expectTypeOf(response).toEqualTypeOf<{ foo: string }>();
    });
  });

  describe("readBody", () => {
    it("untyped", () => {
      defineHandler(async (event) => {
        const body = await readBody(event);
        expectTypeOf(body).toBeUnknown;
      });
    });

    it("typed via generic", () => {
      defineHandler(async (event) => {
        const body = await readBody<string>(event);
        expectTypeOf(body).not.toBeAny();
        expectTypeOf(body!).toBeString;
      });
    });

    it("typed via validator", () => {
      defineHandler(async (event) => {
        const validator = (body: unknown) => body as { id: string };
        const body = await readValidatedBody(event, validator);
        expectTypeOf(body).not.toBeAny();
        expectTypeOf(body).toEqualTypeOf<{ id: string }>;
      });
    });

    it("typed via event handler", () => {
      defineHandler<{ body: { id: string } }>(async (event) => {
        const body = await readBody(event);
        expectTypeOf(body).not.toBeAny();
        expectTypeOf(body).toEqualTypeOf<{ id: string } | undefined>();
      });
    });

    it("typed via validated event handler", () => {
      defineValidatedHandler({
        validate: {
          body: z.object({
            id: z.string(),
          }),
          headers: z.object({
            "x-thing": z.string(),
          }),
          query: z.object({
            search: z.string().optional(),
          }),
        },
        async handler(event) {
          const query = getQuery(event);
          expectTypeOf(query.search).not.toBeAny();
          expectTypeOf(query.search).toEqualTypeOf<string | undefined>();

          // TODO:
          // type PossibleParams = Parameters<typeof event.url.searchParams.get>[0]
          // expectTypeOf<PossibleParams>().toEqualTypeOf<(string & {}) | "search">();

          const value = await event.req.json();
          expectTypeOf(value).toEqualTypeOf<{ id: string }>();

          const body = await readBody(event);
          expectTypeOf(body).not.toBeAny();
          expectTypeOf(body).toEqualTypeOf<{ id: string } | undefined>();
        },
      });
    });
  });

  describe("defineValidatedHandler", () => {
    it("returned handler exposes validated body, query and headers", () => {
      const handler = defineValidatedHandler({
        validate: {
          body: z.object({ title: z.string(), count: z.number() }),
          headers: z.object({ "x-thing": z.string() }),
          query: z.object({ page: z.string().optional() }),
        },
        handler: () => "ok",
      });

      type Req = ReqOf<typeof handler>;

      expectTypeOf<Req["body"]>().toEqualTypeOf<{ title: string; count: number }>();
      expectTypeOf<Req["query"]>().toEqualTypeOf<{ page?: string | undefined }>();
      expectTypeOf<Req["headers"]>().toEqualTypeOf<{ "x-thing": string }>();
    });

    it("keeps array query values", () => {
      const handler = defineValidatedHandler({
        validate: {
          query: z.object({ tag: z.array(z.string()), page: z.string().optional() }),
        },
        handler: (event) => {
          const query = getQuery(event);
          expectTypeOf(query.tag).toEqualTypeOf<string[]>();
          return "ok";
        },
      });

      type Req = ReqOf<typeof handler>;
      expectTypeOf<Req["query"]>().toEqualTypeOf<{ tag: string[]; page?: string | undefined }>();
    });

    it("leaves unvalidated parts of the request empty", () => {
      const bodyOnly = defineValidatedHandler({
        validate: { body: z.object({ title: z.string() }) },
        handler: () => "ok",
      });
      type BodyOnlyReq = ReqOf<typeof bodyOnly>;

      expectTypeOf<BodyOnlyReq["body"]>().toEqualTypeOf<{ title: string }>();
      expectTypeOf<BodyOnlyReq["query"]>().toEqualTypeOf<{}>();
      expectTypeOf<BodyOnlyReq["headers"]>().toEqualTypeOf<{}>();
    });

    it("types the request as unvalidated when no schema is given", () => {
      const unvalidated = defineValidatedHandler({ handler: () => "ok" });
      type UnvalidatedReq = ReqOf<typeof unvalidated>;

      expectTypeOf<UnvalidatedReq["body"]>().toBeUnknown();
      expectTypeOf<UnvalidatedReq["query"]>().toEqualTypeOf<{}>();
      expectTypeOf<UnvalidatedReq["headers"]>().toEqualTypeOf<{}>();
    });

    it("handlers with a concrete request type can be registered on an app", () => {
      const validated = defineValidatedHandler({
        validate: { body: z.object({ title: z.string() }) },
        handler: () => "ok",
      });
      const typed = defineHandler<{ body: { id: string } }, string>(() => "ok");

      new H3().get("/validated", validated).post("/typed", typed).all("/all", validated);

      // @ts-expect-error not an event handler
      new H3().get("/bad", (n: number) => n);
    });
  });

  describe("defineRoute", () => {
    it("keeps the bare RouteDefinition handler untyped", () => {
      expectTypeOf<RouteDefinition["handler"]>().toEqualTypeOf<EventHandler>();
    });

    it("types the handler event from validation schemas", () => {
      defineRoute({
        method: "POST",
        route: "/",
        validate: {
          body: z.object({ title: z.string() }),
          headers: z.object({ "x-thing": z.string() }),
          query: z.object({ tag: z.array(z.string()), page: z.string().optional() }),
        },
        async handler(event) {
          expectTypeOf(await event.req.json()).toEqualTypeOf<{ title: string }>();
          expectTypeOf(await readBody(event)).toEqualTypeOf<{ title: string } | undefined>();
          expectTypeOf(getQuery(event)).toEqualTypeOf<{
            tag: string[];
            page?: string | undefined;
          }>();
          type Req = ReqOf<(e: typeof event) => void>;
          expectTypeOf<Req["headers"]>().toEqualTypeOf<{ "x-thing": string }>();
          return "ok";
        },
      });
    });

    it("leaves unvalidated parts of the request empty", () => {
      defineRoute({
        method: "POST",
        route: "/",
        validate: { body: z.object({ title: z.string() }) },
        handler(event) {
          type Req = ReqOf<(e: typeof event) => void>;
          expectTypeOf<Req["body"]>().toEqualTypeOf<{ title: string }>();
          expectTypeOf<Req["query"]>().toEqualTypeOf<{}>();
          expectTypeOf<Req["headers"]>().toEqualTypeOf<{}>();
          return "ok";
        },
      });
    });

    it("uses the default request type without validation", () => {
      defineRoute({
        method: "GET",
        route: "/",
        handler(event) {
          expectTypeOf(event).toEqualTypeOf<H3Event<EventHandlerRequest>>();
          return "ok";
        },
      });
    });

    it("accepts handlers typed against plain H3Event", () => {
      const plain = (event: H3Event) => event.url.pathname;
      const untyped: EventHandler = plain;
      const validate = { body: z.object({ title: z.string() }) };

      defineRoute({ method: "POST", route: "/", validate, handler: plain });
      defineRoute({ method: "POST", route: "/", validate, handler: untyped });
      defineRoute({ method: "GET", route: "/", handler: untyped });

      const def: RouteDefinition = { method: "GET", route: "/", handler: untyped };
      defineRoute(def);
    });

    it("accepts validate.onError", () => {
      defineRoute({
        method: "POST",
        route: "/",
        validate: {
          body: z.object({ title: z.string() }),
          onError: (result) => {
            expectTypeOf(result._source).toEqualTypeOf<string | undefined>();
            return { status: 422, message: "Invalid", data: result.issues };
          },
        },
        handler: () => "ok",
      });
    });

    it("accepts explicit schema generics", () => {
      const body = z.object({ title: z.string() });
      const def: RouteDefinition<typeof body> = {
        method: "POST",
        route: "/",
        validate: { body },
        handler: async (event) => {
          expectTypeOf(await event.req.json()).toEqualTypeOf<{ title: string }>();
          return "ok";
        },
      };
      defineRoute(def);
    });
  });

  describe("routes", () => {
    it("types the event of an inline method handler", () => {
      new H3().get("/", (event) => {
        expectTypeOf(event).toEqualTypeOf<H3Event<EventHandlerRequest>>();
        return "ok";
      });
    });

    it("types the event of an inline `on` handler", () => {
      new H3().on("GET", "/", (event) => {
        expectTypeOf(event).toEqualTypeOf<H3Event<EventHandlerRequest>>();
        return "ok";
      });
    });

    it("accepts a handler with a concrete request type in an untyped slot", () => {
      expectTypeOf<EventHandler<{ body: { id: string } }>>().toExtend<HTTPHandler>();
    });
  });

  describe("handler passthrough", () => {
    const handler = defineValidatedHandler({
      validate: { body: z.object({ title: z.string() }) },
      handler: () => "ok",
    });

    it("keeps the request type through toEventHandler", () => {
      const normalized = toEventHandler(handler)!;
      expectTypeOf<ReqOf<typeof normalized>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("keeps the request type through withBase", () => {
      const based = withBase("/api", handler);
      expectTypeOf<ReqOf<typeof based>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("keeps the request type through defineLazyEventHandler", () => {
      const lazy = defineLazyEventHandler(() => handler);
      expectTypeOf<ReqOf<typeof lazy>["body"]>().toEqualTypeOf<{ title: string }>();
    });

    it("does not leak any for a plain HTTPHandler", () => {
      const plain = handler as HTTPHandler;

      const normalized = toEventHandler(plain)!;
      expectTypeOf<ReqOf<typeof normalized>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof normalized>>().toEqualTypeOf<EventHandlerRequest>();

      const based = withBase("/api", plain);
      expectTypeOf<ReqOf<typeof based>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof based>>().toEqualTypeOf<EventHandlerRequest>();

      const lazy = defineLazyEventHandler(() => plain);
      expectTypeOf<ReqOf<typeof lazy>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof lazy>>().toEqualTypeOf<EventHandlerRequest>();
    });

    it("uses the default request type for an H3 instance", () => {
      const normalized = toEventHandler(new H3())!;
      expectTypeOf<ReqOf<typeof normalized>>().not.toBeAny();
      expectTypeOf<ReqOf<typeof normalized>>().toEqualTypeOf<EventHandlerRequest>();
    });
  });

  describe("getQuery", () => {
    it("untyped", () => {
      defineHandler((event) => {
        const query = getQuery(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<Partial<Record<string, string | string[]>>>();
      });
    });

    it("typed via generic", () => {
      defineHandler((event) => {
        const query = getQuery<{ id: string }>(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ id: string }>();
      });
    });

    it("typed via validator", () => {
      defineHandler(async (event) => {
        const validator = (body: unknown) => body as { id: string };
        const body = await getValidatedQuery(event, validator);
        expectTypeOf(body).not.toBeAny();
        expectTypeOf(body).toEqualTypeOf<{ id: string }>();
      });
    });

    it("typed via zod schema", () => {
      defineHandler(async (event) => {
        const query = await getValidatedQuery(
          event,
          z.object({
            search: z.string().optional(),
          }),
        );
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ search?: string | undefined }>();
      });
    });

    it("typed via zod schema in defineEventHandler object", () => {
      defineEventHandler({
        async handler(event) {
          const query = await getValidatedQuery(
            event,
            z.object({
              search: z.string().optional(),
            }),
          );
          expectTypeOf(query).not.toBeAny();
          expectTypeOf(query).toEqualTypeOf<{ search?: string | undefined }>();
        },
      });
    });

    it("typed via event handler", () => {
      defineHandler<{ query: { id: string } }>((event) => {
        const query = getQuery(event);
        expectTypeOf(query).not.toBeAny();
        expectTypeOf(query).toEqualTypeOf<{ id: string }>();
      });
    });
  });

  describe("defineWebSocketHandler", () => {
    it("exposes crossws on the returned response type without a cast", () => {
      // https://github.com/h3js/h3/issues/1258
      // Given a WebSocket handler defined via defineWebSocketHandler
      const wsHandler = defineWebSocketHandler({ message: () => {} });
      // When the handler is invoked directly (as crossws adapters do)
      const res = wsHandler({} as H3Event);
      // Then `crossws` must be visible on the returned type, with no `as any` cast
      expectTypeOf(res).toHaveProperty("crossws");
    });

    it("still types the http fallback handler's return value", () => {
      // Given a WebSocket handler with an http fallback returning a string
      const wsHandler = defineWebSocketHandler({ message: () => {} }, () => "hello");
      const res = wsHandler({} as H3Event);
      // Then the returned type is the union of the WebSocket response
      // (with `crossws` visible) and the http handler's return type —
      // neither branch is widened away.
      expectTypeOf(res).toExtend<string | (Response & { crossws?: unknown })>();
      expectTypeOf(res).not.toBeUnknown();
    });

    it("types an async hooks factory's return value without a cast", async () => {
      // Given a WebSocket handler defined with an async hooks factory
      const wsHandler = defineWebSocketHandler(async (_event) => {
        await Promise.resolve();
        return { message: () => {} };
      });
      // When the handler is invoked directly (as crossws adapters do)
      const res = wsHandler({} as H3Event);
      // Then the return type must itself be the union of the sync response
      // and a Promise of it, not just `WebSocketResponse`. Otherwise
      // await-ing a sync-typed value would be a no-op and this assertion
      // would pass regardless of whether the factory was actually awaited.
      expectTypeOf(res).toEqualTypeOf<WebSocketResponse | Promise<WebSocketResponse>>();
      // And the resolved value still exposes `crossws` with no cast.
      const awaited = await res;
      expectTypeOf(awaited).toHaveProperty("crossws");
    });
  });
});

// Route rules are declared empty by h3 and filled in by modules
// (`h3-rules`, Nitro, ...) through declaration merging.
declare module "../../src/index.ts" {
  interface RouteRules {
    swr?: number | boolean;
  }
}

describe("routeRules", () => {
  it("augmented keys merge into the interface used by the event context", () => {
    defineHandler((event) => {
