      detail: unhandled ? undefined : this.message,
      instance: unhandled ? undefined : this.instance,
    };
  }
}

// --- internal ---

function stringField(source: unknown, key: "type" | "instance"): string | undefined {
  const value = (source as Record<string, unknown> | undefined | null)?.[key];
  return typeof value === "string" && value ? value : undefined;
}

